#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

vector<int> multiplyModulo(const vector<int>& a, const vector<int>& b, int m) {
    int lengthNeeded = a.size() + b.size() - 1;
    int nSize = 1 << (32 - __builtin_clz(lengthNeeded - 1));
    vector<double> reA(nSize, 0), imA(nSize, 0);
    for (size_t i = 0; i < a.size(); i++) {
        int xCoord = a[i] % m;
        reA[i] = xCoord & ((1 << 15) - 1);
        imA[i] = xCoord >> 15;
    }
    performFFT(reA, imA, false);
