        reB[i] = xCoord & ((1 << 15) - 1);
        imB[i] = xCoord >> 15;
    }
    performFFT(reB, imB, false);
    vector<double> reA2(nSize, 0), imA2(nSize, 0);
    vector<double> reB2(nSize, 0), imB2(nSize, 0);
    for (int i = 0; i < nSize; i++) {
