        double a1i = (imA[i] - imA[j]) / 2.0;
        double a2r = (imA[i] + imA[j]) / 2.0;
        double a2i = (reA[j] - reA[i]) / 2.0;
        double b1r = (reB[i] + reB[j]) / 2.0;
        double b1i = (imB[i] - imB[j]) / 2.0;
        double b2r = (imB[i] + imB[j]) / 2.0;
        double b2i = (reB[j] - reB[i]) / 2.0;
        reA2[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        imA2[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        reB2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        imB2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }
    performFFT(reA2, imA2, true);
    performFFT(reB2, imB2, true);
    vector<int> resArr(lengthNeeded, 0);
    for (int i = 0; i < lengthNeeded; i++) {
        long long aa = round(reA2[i]);
        long long bb = round(reB2[i]);
        long long cc = round(imA2[i]);
        resArr[i] = (int)((aa + (bb << 15) + (cc << 30)) % m);
    }
    return resArr;
}

void performFFT(vector<double>& re, vector<double>& im, bool invert) {
    int n = re.size();
    int shiftCalc = 32 - __builtin_clz(n);
    for (int i = 1; i < n; i++) {
        int j = __builtin_bswap32(i << shiftCalc) >> (32 - shiftCalc);
        if (i < j) {
            swap(re[i], re[j]);
            swap(im[i], im[j]);
        }
    }
